<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app';import { ref } from 'vue';import { api } from '../../services/api';
const id=ref('');const item=ref<any>(null);const feedback=ref('');const working=ref(false);
async function load(){try{item.value=await api(`/me/tasks/${id.value}`);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function act(){working.value=true;try{if(item.value.completionMode==='SIMPLE')await api(`/me/tasks/${id.value}/complete`,'POST');else await api(`/me/tasks/${id.value}/submissions`,'POST',{feedback:feedback.value});uni.showToast({title:'提交成功',icon:'success'});feedback.value='';await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{working.value=false;}}
onLoad(q=>{id.value=String(q?.id??'');load();});
</script>
<template><view class="page"><view v-if="!item" class="empty">正在加载…</view><template v-else><view class="card"><view class="meta"><text class="badge">{{item.completionMode==='SIMPLE'?'简单完成':'审核完成'}}</text><text :class="item.derivedStatus?.startsWith('OVERDUE')?'danger':'muted'">{{item.derivedStatus}}</text></view><text class="title">{{item.title}}</text><text class="deadline">截止：{{new Date(item.deadlineAt).toLocaleString()}}</text><view class="divider"/><text class="body">{{item.content}}</text></view><view v-if="item.submissions?.length" class="card"><text class="section-title">提交记录</text><view v-for="s in item.submissions" :key="s.id" class="history"><text>第 {{s.submissionNo}} 次 · {{s.reviewStatus}}</text><text class="muted">{{s.feedback||'无文字反馈'}}</text><text v-if="s.reviewComment" class="comment">审核意见：{{s.reviewComment}}</text></view></view><view v-if="item.completionMode==='REVIEW' && ['PENDING','RETURNED'].includes(item.recordStatus)" class="card"><text class="section-title">完成反馈</text><textarea v-model="feedback" class="textarea" placeholder="请填写完成情况" maxlength="5000" /></view><button v-if="item.completionMode==='SIMPLE'&&item.recordStatus==='PENDING'" class="primary-btn" :loading="working" @tap="act">标记已完成</button><button v-if="item.completionMode==='REVIEW'&&['PENDING','RETURNED'].includes(item.recordStatus)" class="primary-btn" :loading="working" @tap="act">提交审核</button><view v-if="['APPROVED','COMPLETED'].includes(item.recordStatus)" class="done">✓ 任务已完成</view><view v-if="item.recordStatus==='SUBMITTED'" class="waiting">已提交，等待管理员审核</view></template></view></template>
<style scoped>.meta{display:flex;justify-content:space-between}.badge{padding:8rpx 14rpx;color:#fff;font-size:21rpx;border-radius:10rpx;background:#e58648}.title{display:block;margin:28rpx 0 14rpx;font-size:38rpx;font-weight:800}.deadline{color:#e07a42;font-size:24rpx}.divider{height:1px;margin:28rpx 0;background:#edf1f1}.body{white-space:pre-wrap;line-height:1.8}.history{padding:20rpx 0;border-top:1px solid #edf1f1}.history text{display:block;margin-top:8rpx}.comment{color:#bd6737}.textarea{min-height:220rpx;padding:20rpx;border:1px solid #dbe7e8;border-radius:16rpx;background:#f8fbfb}.done,.waiting{padding:25rpx;text-align:center;border-radius:18rpx}.done{color:#19866f;background:#e9f8f3}.waiting{color:#9b6c26;background:#fff6df}</style>
